private void xrTableCell6_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {

            if (sasia != 0)
            {
                e.Result = shuma / sasia;
            }
            else
            {
                e.Result = shuma;
            }
            e.Handled = true;	
}



private void xrTableCell6_SummaryReset(object sender, System.EventArgs e) {
	      shuma = 0;
            sasia = 0;
	System.Resources.ResourceManager rm = new System.Resources.ResourceManager("Resources.Strings", System.Reflection.Assembly.Load("App_GlobalResources"));
            var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
            var filtri = parameters.Find(param => param.Emri == "filterCmimMePaTVSH");
		tvsh=!(filtri.Vlera == "Cmimi pa TVSH");
}


private void xrTableCell6_SummaryRowChanged(object sender, System.EventArgs e) {

            if( GetCurrentColumnValue("CMIMI") != null &&  GetCurrentColumnValue("CMIMI") != System.DBNull.Value
     && GetCurrentColumnValue("SASIA")!= null &&  GetCurrentColumnValue("SASIA") != System.DBNull.Value)
		{
			decimal koeficenti = 1m;
			decimal sasi=Convert.ToDecimal(GetCurrentColumnValue("SASIA"));
			decimal pesha=sasi*Convert.ToDecimal(GetCurrentColumnValue("CMIMI"))*Convert.ToDecimal(GetCurrentColumnValue("KURSI"));
			if(tvsh&&GetCurrentColumnValue("Tvsh1")!= null&&GetCurrentColumnValue("Tvsh1") != System.DBNull.Value)
				koeficenti +=Convert.ToDecimal(GetCurrentColumnValue("Tvsh1"))*0.01m;
			shuma+=koeficenti*pesha;
			sasia+=sasi;
		}


      //    if(tvsh&&GetCurrentColumnValue("VLEFTAMETVSH") != null){
