 private void CmimiKoka_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {
            System.Resources.ResourceManager rm = new System.Resources.ResourceManager("Resources.Strings", System.Reflection.Assembly.Load("App_GlobalResources"));
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);          
  var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
            var gjuharap = this.Extensions["raportgjuha"];
            var filtri = parameters.Find(param => param.Emri == "filterCmimMePaTVSH");
            if (filtri.Vlera == "Cmimi pa TVSH")
                CmimiKokaR.Text = CmimiKoka.Text = rm.GetString("labelCmimiPaTvsh", parametraRaporti.Ci);
            else
                CmimiKokaR.Text = CmimiKoka.Text = rm.GetString("labelRaportCmimiMeTVSH", parametraRaporti.Ci);
        }

